/* eslint-disable no-console */
import React, { useState } from "react";
import { MapContainer, TileLayer, Marker, Popup } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

export default function SafetyCheck() {
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [result, setResult] = useState("");
  const [position, setPosition] = useState(null);

  const handleFetchLocation = () => {
    if (!navigator.geolocation) {
      alert("Geolocation is not supported by your browser.");
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords;
        setLatitude(latitude);
        setLongitude(longitude);
        setPosition([latitude, longitude]);
      },
      (err) => {
        console.error("Error fetching location:", err);
        alert("Unable to fetch location. Please allow location access.");
      }
    );
  };

  const handleCheckSafety = async () => {
    try {
      const response = await fetch("http://localhost:5000/api/safety/check", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          latitude: parseFloat(latitude),
          longitude: parseFloat(longitude),
        }),
      });

      const data = await response.json();
      setResult(data.message);
    } catch (error) {
      console.error("Error checking safety:", error);
      setResult("Error checking safety");
    }
  };

  const markerIcon = new L.Icon({
    iconUrl: "https://cdn-icons-png.flaticon.com/512/854/854878.png",
    iconSize: [35, 35],
  });

  return (
    <div
      style={{
        textAlign: "center",
        marginTop: "30px",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      <h2>🌍 Smart Tourist Safety Check</h2>
      <div style={{ marginBottom: "10px" }}>
        <button
          onClick={handleFetchLocation}
          style={{
            marginRight: "10px",
            padding: "8px 16px",
            backgroundColor: "#0077b6",
            color: "white",
            border: "none",
            borderRadius: "5px",
          }}
        >
          📍 Fetch My Location
        </button>
        <button
          onClick={handleCheckSafety}
          style={{
            padding: "8px 16px",
            backgroundColor: "#00b894",
            color: "white",
            border: "none",
            borderRadius: "5px",
          }}
        >
          ✅ Check Safety
        </button>
      </div>

      {result && (
        <p style={{ marginTop: "10px", fontWeight: "bold", color: "#222" }}>
          {result}
        </p>
      )}

      <div
        style={{
          width: "90%",
          height: "400px",
          margin: "20px auto",
          borderRadius: "10px",
          overflow: "hidden",
          boxShadow: "0 4px 10px rgba(0,0,0,0.2)",
        }}
      >
        <MapContainer
          center={position || [25.3176, 82.9739]}
          zoom={13}
          style={{ height: "100%", width: "100%" }}
        >
          <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
          {position && (
            <Marker position={position} icon={markerIcon}>
              <Popup>
                You are here 📍
                <br />
                Lat: {latitude}
                <br />
                Lng: {longitude}
              </Popup>
            </Marker>
          )}
        </MapContainer>
      </div>
    </div>
  );
}
